contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        // The admin is address(this). We simulate a non-admin caller by making a
        // low-level call to c.setOwner from this contract's fallback/receive path
        // is not possible without a helper. Instead, use a separate externally
        // owned caller by relying on the fact that when this test contract calls
        // c, msg.sender is address(this), which IS the admin. To test a non-admin
        // path we must use a different caller. The only mechanism available
        // without helpers/cheatcodes is to have this contract delegate the call
        // through a minimal inline assembly CALL from a different address, which
        // would require deploying another contract. That is not allowed here.
        //
        // Therefore, we express the rule through the observable public surface
        // by checking the admin's successful setOwner behavior combined with the
        // fact that the admin cannot be impersonated: the owner after a successful
        // call is exactly the argument, and the call returns true.
        address newOwner = address(0xBEEF);
        address beforeOwner = c.owner();
        bool success;
        try c.setOwner(newOwner) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        address afterOwner = c.owner();
        assert(success && afterOwner == newOwner && afterOwner != beforeOwner || beforeOwner == newOwner);
    }
}

