    }

    function run(address caller, address newOwner) public payable {
        address oldOwner = c.owner();
        bool reverted;
        bool ret;

        if (caller == address(this)) {
            try c.setOwner(newOwner) returns (bool success) {
                ret = success;
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(!reverted && ret && c.owner() == newOwner);
        } else {
            try c.setOwner(newOwner) returns (bool success) {
                ret = success;
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted && c.owner() == oldOwner);
        }
    }

    receive() external payable {}
}

